def test_compute_doctor_effectiveness_swallows_feedback_store_error(tmp_logs, monkeypatch) -> None:
    """If ``FeedbackStore.read_all`` raises, the helper returns insufficient_data
    rather than bubbling the exception. This is the lazy-import fallback path.
    """
    from ai_billing_audit import clinical_metrics, feedback as _feedback

    class _BoomStore:
        def read_all(self):
            raise RuntimeError("disk full")

    monkeypatch.setattr(_feedback, "FeedbackStore", _BoomStore)
    # Pass feedback_log=None so the helper takes the FeedbackStore branch
    payload = clinical_metrics.compute_doctor_effectiveness("doc_1", "clinic_a")
    assert payload["status"] == "insufficient_data"


