def _seed_incorrect_feedback_row(path: Path, **fields) -> None:
    """Append a raw JSON line to FEEDBACK_LOG (the helper reads the file
    directly because FeedbackStore rejects 'incorrect' as an action).
    """
    row = {
        "encounter_id": "e1",
        "finding_id": "f1",
        "action": "incorrect",
        "doctor_id": "doctor_1",
        "clinic_id": "clinic_a",
        "rule_id": "r1",
        "severity": "low",
        "category": "documentation",
        "biller_id": "doctor_1",
        "timestamp": "2026-06-25T00:00:00Z",
        "event_id": "fb_seed_1",
    }
    row.update(fields)
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as fh:
        fh.write(json.dumps(row) + "\n")


