# Pre-submit block (t_d080595b)
# ---------------------------------------------------------------------------


def test_record_pre_submit_block_round_trip(tmp_logs) -> None:
    from ai_billing_audit.clinical_metrics import (
        list_pre_submit_blocks,
        record_pre_submit_block,
    )

    record_pre_submit_block(
        "clinic_a", encounter_id="enc_1", finding_count=3,
        blocked=True, override_reason="",
    )
    record_pre_submit_block(
        "clinic_a", encounter_id="enc_2", finding_count=2,
        blocked=True, override_reason="patient is terminal, billing is moot",
    )
    rows = list_pre_submit_blocks("clinic_a")
    assert len(rows) == 2
    assert rows[1]["override_reason"].startswith("patient")
    assert list_pre_submit_blocks("other") == []


