def test_record_extension_audit_round_trip(tmp_logs) -> None:
    from ai_billing_audit.clinical_metrics import record_extension_audit

    payload = record_extension_audit(
        clinic_id="clinic_a", ehr="athena", encounter_id="enc_1",
        findings_count=2, user_action="edited_then_submitted",
        extension_version="0.4.1",
    )
    assert payload["ehr"] == "athena"
    assert payload["user_action"] == "edited_then_submitted"
    assert payload["extension_version"] == "0.4.1"


@pytest.mark.parametrize("bad_ehr", ["bogus_ehr", "EPIC", "", "advanced"])
def test_record_extension_audit_bad_ehr_raises(tmp_logs, bad_ehr) -> None:
    from ai_billing_audit.clinical_metrics import record_extension_audit

    with pytest.raises(ValueError, match="ehr must be one of"):
        record_extension_audit(
            clinic_id="clinic_a", ehr=bad_ehr, encounter_id="enc_1",
            findings_count=0, user_action="submitted", extension_version="0.0",
        )


@pytest.mark.parametrize(
    "bad_action", ["panic_clicked", "edited", "", "SUBMITTED"],
)
def test_record_extension_audit_bad_user_action_raises(tmp_logs, bad_action) -> None:
    from ai_billing_audit.clinical_metrics import record_extension_audit

    with pytest.raises(ValueError, match="user_action must be"):
        record_extension_audit(
            clinic_id="clinic_a", ehr="athena", encounter_id="enc_1",
            findings_count=0, user_action=bad_action, extension_version="0.0",
        )


# ---------------------------------------------------------------------------
# Specialty mix (t_da44c384)
# ---------------------------------------------------------------------------


def test_compute_specialty_mix_sums_to_one(tmp_logs) -> None:
    """The mix dict's values must sum to ~1.0."""
    from ai_billing_audit.clinical_metrics import compute_specialty_mix

    encounters = ["primary_care"] * 60 + ["surgery"] * 30 + ["psych"] * 10
    payload = compute_specialty_mix(
        clinic_id="clinic_a", encounter_specialties=encounters,
    )
    assert payload["encounter_count"] == 100
    assert abs(sum(payload["specialty_mix"].values()) - 1.0) < 0.01


def test_compute_specialty_mix_dominant_ordering(tmp_logs) -> None:
    """``dominant_specialties`` is sorted by share, descending, top 3."""
    from ai_billing_audit.clinical_metrics import compute_specialty_mix

    encounters = ["primary_care"] * 60 + ["surgery"] * 30 + ["psych"] * 10
    payload = compute_specialty_mix(
        clinic_id="clinic_a", encounter_specialties=encounters,
    )
    assert payload["dominant_specialties"][0] == "primary_care"
    assert payload["dominant_specialties"][1] == "surgery"


def test_compute_specialty_mix_normalises_case(tmp_logs) -> None:
    """Inputs are lowercased + stripped before counting."""
    from ai_billing_audit.clinical_metrics import compute_specialty_mix

    payload = compute_specialty_mix(
        clinic_id="clinic_a",
        encounter_specialties=["  Primary_Care ", "PRIMARY_CARE", "primary_care"],
    )
    assert payload["specialty_mix"]["primary_care"] == 1.0


def test_compute_specialty_mix_ignores_blank_strings(tmp_logs) -> None:
    """Whitespace-only entries are skipped, not crashed on."""
    from ai_billing_audit.clinical_metrics import compute_specialty_mix

    payload = compute_specialty_mix(
        clinic_id="clinic_a",
        encounter_specialties=["", "   ", "primary_care"],
    )
    assert payload["encounter_count"] == 1


def test_compute_specialty_mix_empty_raises(tmp_logs) -> None:
    from ai_billing_audit.clinical_metrics import compute_specialty_mix

    with pytest.raises(ValueError, match="non-empty"):
        compute_specialty_mix(clinic_id="clinic_a", encounter_specialties=[])


def test_get_specialty_mix_returns_latest_or_none(tmp_logs) -> None:
    from ai_billing_audit.clinical_metrics import (
        compute_specialty_mix,
        get_specialty_mix,
    )

    assert get_specialty_mix("clinic_a") is None

    compute_specialty_mix(
        clinic_id="clinic_a", encounter_specialties=["primary_care"],
    )
    compute_specialty_mix(
        clinic_id="clinic_a", encounter_specialties=["surgery"],
    )
    payload = get_specialty_mix("clinic_a")
    assert payload is not None
    assert "surgery" in payload["specialty_mix"]

    assert get_specialty_mix("other") is None


# ---------------------------------------------------------------------------
# Bulk-accept pattern (t_f3d392b2)
# ---------------------------------------------------------------------------


def test_detect_bulk_accept_pattern_below_threshold_returns_none(tmp_logs) -> None:
    from ai_billing_audit.clinical_metrics import detect_bulk_accept_pattern

    assert detect_bulk_accept_pattern(
        "clinic_a", rule_id="mod_25", dismissal_count=5,
    ) is None


def test_detect_bulk_accept_pattern_above_threshold_persists(tmp_logs) -> None:
    from ai_billing_audit.clinical_metrics import detect_bulk_accept_pattern

    proposal = detect_bulk_accept_pattern(
        "clinic_a", rule_id="mod_25", dismissal_count=12,
    )
    assert proposal is not None
    assert proposal["opt_in"] is False
    assert proposal["clinic_id"] == "clinic_a"
    assert proposal["rule_id"] == "mod_25"
    assert proposal["dismissal_count"] == 12
    assert len(proposal["event_id"]) == 32


def test_detect_bulk_accept_pattern_custom_min_dismissals(tmp_logs) -> None:
    """The default min_dismissals=10 can be raised per call."""
    from ai_billing_audit.clinical_metrics import detect_bulk_accept_pattern

    # 12 dismissals, min_dismissals=20 → still below threshold
    assert detect_bulk_accept_pattern(
        "clinic_a", rule_id="mod_25", dismissal_count=12, min_dismissals=20,
    ) is None
    # 25 dismissals, min_dismissals=20 → proposal emitted
    proposal = detect_bulk_accept_pattern(
        "clinic_a", rule_id="mod_25", dismissal_count=25, min_dismissals=20,
    )
    assert proposal is not None


def test_opt_in_bulk_accept_round_trip(tmp_logs) -> None:
    from ai_billing_audit.clinical_metrics import (
        detect_bulk_accept_pattern,
        opt_in_bulk_accept,
    )

    proposal = detect_bulk_accept_pattern(
        "clinic_a", rule_id="mod_25", dismissal_count=12,
    )
    assert proposal is not None
    pattern_id = proposal["event_id"]

    opted = opt_in_bulk_accept(pattern_id, actor="biller_1")
    assert opted["opt_in"] is True
    assert opted["opt_in_actor"] == "biller_1"
    assert "opt_in_at" in opted


def test_opt_in_bulk_accept_unknown_pattern_raises(tmp_logs) -> None:
    from ai_billing_audit.clinical_metrics import opt_in_bulk_accept

    with pytest.raises(ValueError, match="not found"):
        opt_in_bulk_accept("nonexistent_id")


