def test_queue_doctor_positive_digest_round_trip(tmp_logs) -> None:
    from ai_billing_audit.clinical_metrics import (
        list_doctor_positive_digests,
        queue_doctor_positive_digest,
    )

    payload = queue_doctor_positive_digest(
        "doc_1", "clinic_a", week_of="2026-W26",
        notes_written=47, notes_clean=45, notes_with_quick_fix=2,
        estimated_savings_usd=9200.0,
    )
    assert payload["status"] == "queued"
    assert payload["notes_clean"] == 45
    assert payload["week_of"] == "2026-W26"

    digests = list_doctor_positive_digests("doc_1")
    assert len(digests) == 1
    assert digests[0]["clinic_id"] == "clinic_a"
    # Other doctor: isolation
    assert list_doctor_positive_digests("other_doc") == []